SELECT p.status, p.close_reason, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losses, SUM(p.realized_pnl) AS pnl_sum, AVG(TIMESTAMPDIFF(SECOND, p.opened_at, p.closed_at)) AS avg_hold_s FROM paper_position p WHERE p.opened_at BETWEEN '2026-10-10 00:15:21' AND '2026-10-11 10:00:03' AND p.closed_at IS NOT NULL AND (SELECT s2.decision FROM trade_signal s2 WHERE s2.symbol = p.symbol AND s2.interval_code = '1h' AND s2.generated_at <= p.opened_at ORDER BY s2.generated_at DESC LIMIT 1) IN ('SELL','STRONG_SELL') GROUP BY p.status, p.close_reason ORDER BY n DESC